import{_ as e,c as r,o,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Logs settings","description":"","frontmatter":{"title":"Logs settings"},"headers":[],"relativePath":"logs/settings.md","filePath":"logs/settings.md"}'),a={name:"logs/settings.md"};function n(d,t,i,l,g,h){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="logs-settings" tabindex="-1">Logs settings <a class="header-anchor" href="#logs-settings" aria-label="Permalink to &quot;Logs settings&quot;">​</a></h1><p><strong>Options → Logs</strong> collects the settings of the <a href="./general.html">Logs</a> tab. Changes apply immediately.</p><hr><h2 id="search-settings" tabindex="-1">Search Settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search Settings&quot;">​</a></h2><p>Default search modes of the <strong>Logs</strong> tab:</p><table tabindex="0"><thead><tr><th>Option</th><th>Searches in</th></tr></thead><tbody><tr><td><strong>Search by event name</strong></td><td>Title, component, store, URL (enabled by default)</td></tr><tr><td><strong>Search by key</strong></td><td>Keys in the payload and changed paths</td></tr><tr><td><strong>Search by value</strong></td><td>Values in the payload</td></tr></tbody></table><hr><h2 id="ignore-list" tabindex="-1">Ignore list <a class="header-anchor" href="#ignore-list" aria-label="Permalink to &quot;Ignore list&quot;">​</a></h2><p>Event groups added with <strong>Ignore</strong> in the <strong>Logs</strong> tab. Events of these groups are not recorded.</p><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Event type</td></tr><tr><td><strong>Event</strong></td><td>Group key: request (method and path), component, store, etc.</td></tr><tr><td><strong>Added</strong></td><td>Date the rule was added</td></tr></tbody></table><ul><li><strong>Log again</strong> in the row menu removes one rule.</li><li><strong>Log all again</strong> removes all rules.</li></ul><p>The same list is available from the <strong>ignored</strong> indicator in the <strong>Logs</strong> toolbar.</p><hr><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Format of <strong>Export Logs</strong> and of single-event exports:</p><ul><li><strong>JSON</strong> — raw events for re-import or tools;</li><li><strong>HTML</strong> (default) — static report that opens in any browser and can be re-imported.</li></ul><p>Details: <a href="./export.html">Export and import</a>.</p><hr><h2 id="logs-limits" tabindex="-1">Logs limits <a class="header-anchor" href="#logs-limits" aria-label="Permalink to &quot;Logs limits&quot;">​</a></h2><p>Each event type is a <strong>ring buffer</strong>: when it is full, the oldest events are overwritten. The memory budget applies to all types together.</p><h3 id="events-per-type" tabindex="-1">Events per type <a class="header-anchor" href="#events-per-type" aria-label="Permalink to &quot;Events per type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th><th>Unit</th></tr></thead><tbody><tr><td><strong>Network</strong></td><td>500</td><td>requests</td></tr><tr><td><strong>Props changes</strong></td><td>1 000</td><td>events</td></tr><tr><td><strong>Emits</strong></td><td>1 000</td><td>events</td></tr><tr><td><strong>Pinia changes</strong></td><td>1 000</td><td>events</td></tr><tr><td><strong>Store actions</strong></td><td>1 000</td><td>events</td></tr><tr><td><strong>Navigation</strong></td><td>200</td><td>events</td></tr><tr><td><strong>JS errors</strong></td><td>200</td><td>events</td></tr></tbody></table><p>Allowed range: <strong>10 – 20 000</strong>. The number before the field shows how many events of the type are currently stored. For <strong>Network</strong> the limit applies separately to <strong>Send request</strong> and <strong>Receive response</strong> events.</p><h3 id="data-size" tabindex="-1">Data size <a class="header-anchor" href="#data-size" aria-label="Permalink to &quot;Data size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Memory budget</strong></td><td>64 MB</td><td>8 – 1024 MB</td><td>Total size of all buffered events (approximate serialized size)</td></tr><tr><td><strong>Max event size</strong></td><td>512 KB</td><td>16 – 16 384 KB</td><td>Larger parts of an event (store snapshots, arguments, results) are dropped, network bodies are cut to this size</td></tr></tbody></table><p>The bar under the fields shows current usage (<strong>Used X of Y</strong>); it turns orange above 90 %.</p><p>Values outside the range are corrected to the nearest bound. <strong>Defaults</strong> restores all limits.</p><hr><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking {#data-masking}&quot;">​</a></h2><p>Values are masked <strong>when an event is captured</strong>, so they never reach the <strong>Logs</strong> view, exports or imports.</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Mask sensitive data</strong></td><td>Enables masking (on by default)</td></tr><tr><td><strong>Mask token-like values in any text</strong></td><td>Masks <strong>JWT</strong>, <strong>Bearer</strong> / <strong>Basic</strong> credentials and card numbers inside any string</td></tr><tr><td><strong>Key contains</strong> list</td><td>Object keys, header and parameter names containing these fragments are masked</td></tr></tbody></table><p>Default keys: <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code>, <code>token</code>, <code>authorization</code>, <code>cookie</code>, <code>apikey</code>, <code>sessionid</code>, <code>privatekey</code>, <code>creditcard</code>, <code>cardnumber</code>, <code>cvv</code>, <code>cvc</code>, <code>ssn</code>, <code>otp</code>.</p><p>Keys match case-insensitively and ignore separators (<code>api_key</code>, <code>api-key</code> and <code>apiKey</code> are the same). Fragments of <strong>4 letters or fewer</strong> must match a whole word, so <code>pwd</code> or <code>otp</code> do not mask unrelated keys.</p><p>Add your own fragments in the input under the list; remove them from the row menu. <strong>Default keys</strong> restores the default list.</p><p>Masked values are replaced with markers: <code>[MASKED]</code> for values of sensitive keys, <code>[MASKED JWT]</code> and <code>[MASKED CARD]</code> for tokens and card numbers found in text (card numbers are checked with the Luhn algorithm).</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general.html">Working with logs</a></li><li><a href="./export.html">Export and import</a></li><li><a href="/qa-tools/docs/options/settings_management.html">Settings management</a></li></ul>',38)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
